/// @group Surface
/// @sort 0
uniform float A = 0.5;
/// @group Surface|Detail
/// @sort 10
uniform float B = 0.25;
/// @sort 32
uniform float Loose = 1.0;
// `Group("G") { }` stamps the group and an automatic sort (0, 10, 20 ...); nesting composes with `|`.
/// @name M_LpGroupScope
export void M_LpGroupScope(inout material Base)
{
    float Value = 0;
    Value = A + B + Loose;
    Base.Opacity = Value;
}
